set -eu
experiment_root="$HOME/research/icl-dynamics/exp_001_hardware_check"
cd "$experiment_root"
if [ -f supervisor.pid ]; then
 previous_pid="$(cat supervisor.pid)"
 if ps -p "$previous_pid" -o args= | grep -Fq 'bash supervisor_wsl.sh'; then kill "$previous_pid"; fi
fi
if ps -p 547 -o args= | grep -Fq 'venv/bin/python -m pip install'; then
 kill -INT 547
 for attempt in $(seq 1 20); do
  if ! kill -0 547 2>/dev/null; then break; fi
  sleep .2
 done
 if kill -0 547 2>/dev/null; then echo 'Old installer still active; refusing concurrent install'; exit 1; fi
fi
printf '%s' '' | base64 -d | tar -xzf -
nohup setsid bash -c 'python3 -u install_verified_wheels.py > verified_install.log 2>&1; code=$?; printf "%s\n" "$code" > verified_install.exit_code; exit "$code"' > installer_launcher.log 2>&1 < /dev/null &
echo "$!" > verified_install.pid
nohup setsid bash supervisor_wsl.sh > supervisor.log 2>&1 < /dev/null &
echo "$!" > supervisor.pid
printf 'installer_pid='; cat verified_install.pid
printf 'supervisor_pid='; cat supervisor.pid
